CREATE OR REPLACE FUNCTION public.lab_arena_sep18_published_rerun299_score_namespace_guard_v1()
RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public
AS $sep18_published_rerun299_score_namespace_guard$
BEGIN
  IF NEW.round_id = 'arena-2026-09-18'
     AND NEW.submission_id = 'baseline-2026-09-18'
     AND NEW.kind = 'score'
     AND EXISTS (
       SELECT 1 FROM public.lab_arena_rounds
       WHERE round_id = 'arena-2026-09-18-rerun298archive'
     )
     AND NEW.assignment_id IS DISTINCT FROM
           NEW.round_id || ':' || NEW.submission_id || ':' ||
           NEW.stage::TEXT || ':' || NEW.icp_position::TEXT ||
           ':score:rerun299' THEN
    RAISE EXCEPTION 'Sep18 rerun299 scoring requires exact baseline namespace'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$sep18_published_rerun299_score_namespace_guard$;
ALTER FUNCTION public.lab_arena_sep18_published_rerun299_score_namespace_guard_v1()
  OWNER TO lab_arena_owner;
REVOKE ALL ON FUNCTION public.lab_arena_sep18_published_rerun299_score_namespace_guard_v1()
  FROM PUBLIC, anon, authenticated, service_role, lab_arena_service;
DROP TRIGGER IF EXISTS lab_arena_sep18_published_rerun299_score_namespace_guard
  ON public.lab_arena_runs;
CREATE TRIGGER lab_arena_sep18_published_rerun299_score_namespace_guard
  BEFORE INSERT ON public.lab_arena_runs
  FOR EACH ROW
  EXECUTE FUNCTION public.lab_arena_sep18_published_rerun299_score_namespace_guard_v1();

