REVOKE ALL ON FUNCTION public.lab_arena_sep18_published_rerun299_publication_guard_v1()
  FROM PUBLIC, anon, authenticated, service_role, lab_arena_service;
DROP TRIGGER IF EXISTS lab_arena_sep18_published_rerun299_publication_guard
  ON public.lab_arena_rounds;
CREATE TRIGGER lab_arena_sep18_published_rerun299_publication_guard
  BEFORE UPDATE ON public.lab_arena_rounds
  FOR EACH ROW
  EXECUTE FUNCTION public.lab_arena_sep18_published_rerun299_publication_guard_v1();

